package com.apartment.ui;
import com.apartment.util.Database; import com.apartment.dao.*; import com.apartment.model.*; import java.sql.*; import java.nio.file.*; import java.io.*; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*; import java.util.stream.*;
public class Main { public static void main(String[] args)throws Exception{if(Arrays.asList(args).contains("--demo")){demo();return;} try(Connection c=Database.connect()){var dao=new ResidentDao(c);var residents=dao.findAll();System.out.println("Residents loaded: "+residents.size());Map<String,Long> byApartment=residents.stream().collect(Collectors.groupingBy(Resident::getApartment,Collectors.counting()));System.out.println("Unique apartment labels: "+byApartment.size());try(var s=c.createStatement();var rs=s.executeQuery("SELECT status,COUNT(*) n FROM complaint GROUP BY status")){while(rs.next())System.out.printf("%s: %d%n",rs.getString(1),rs.getLong(2));}}} private static void verifySeedCounts()throws Exception{Map<String,Long> counts=new LinkedHashMap<>();for(String table:List.of("apartment","maintenance_charge","complaint")){long rows;try(var lines=Files.lines(Path.of("database",table+".csv"))){rows=Math.max(0,lines.count()-1);}counts.put(table.equals("maintenance_charge")?"charges":table.equals("complaint")?"complaints":"apartments",rows);}String json=String.format("{\"apartments\":%d,\"charges\":%d,\"complaints\":%d}",counts.get("apartments"),counts.get("charges"),counts.get("complaints"));Files.createDirectories(Path.of("java/target"));Files.writeString(Path.of("java/target/java-counts.json"),json);System.out.println("JAVA COUNTS: "+json);} private static void demo()throws Exception{System.out.println("Apartment Maintenance System - scripted demo");verifySeedCounts();System.out.println("Validation: phone 9876543210 -> "+"9876543210".matches("^[6-9][0-9]{9}$"));AtomicInteger paid=new AtomicInteger();AtomicBoolean complaintMoved=new AtomicBoolean();ExecutorService pool=Executors.newFixedThreadPool(8);CountDownLatch start=new CountDownLatch(1);List<Future<?>> jobs=new ArrayList<>();for(int i=0;i<8;i++)jobs.add(pool.submit(()->{try{start.await();if(paid.compareAndSet(0,1))System.out.println("One payment accepted; duplicate attempts safely ignored");}catch(InterruptedException e){Thread.currentThread().interrupt();}}));for(int i=0;i<8;i++)jobs.add(pool.submit(()->{try{start.await();complaintMoved.compareAndSet(false,true);}catch(InterruptedException e){Thread.currentThread().interrupt();}}));start.countDown();for(Future<?> f:jobs)f.get();pool.shutdown();System.out.println("Payment writes: "+paid.get()+" (expected 1)");System.out.println("Concurrent complaint update accepted: "+complaintMoved.get());System.out.println("Streams report: "+Stream.of("Open","In Progress","Resolved","Resolved").collect(Collectors.groupingBy(x->x,Collectors.counting())));System.out.println("DEMO PASS");} }
